    private val applied = mutableListOf<com.nuvio.app.features.watchprogress.WatchProgressEntry>()
    private val saved = mutableListOf<com.nuvio.app.features.library.LibraryItem>()

    @BeforeTest
    fun setUp() {
        val answers = mapOf("/api/user/watchlist" to watchlist, "/api/user/history" to history, "/api/continuar-assistindo" to resume)
        ObaflixDataImport.get = { path -> 200 to answers.getValue(path) }
        ObaflixDataImport.applyProgress = { applied += it }
        ObaflixDataImport.isSaved = { _, _ -> false }
        ObaflixDataImport.save = { saved += it }
        ObaflixDataImport.activeProfile = { 1 }
        ObaflixDataImport.currentUser = { "u1" }
    }

    @AfterTest
    fun tearDown() = ObaflixDataImport.reset()

    @Test
    fun theRealServerAnswersImportWithoutInvalidItemsAndFeedTheLibraryAndTheHomeRow() = runTest {
        val outcome = ObaflixDataImport.run("u1")
        assertEquals(0, outcome.skippedInvalid)
        assertTrue(outcome.complete) // far below the 20/24 caps
        assertEquals(2, saved.size)
        assertTrue(saved.all { it.id.startsWith("obaflix:filme:") && it.type == "movie" && it.name.isNotBlank() })
        assertTrue(applied.isNotEmpty())
        val row = applied.continueWatchingEntries() // the Home "Continuar assistindo" projection
        assertTrue(row.isNotEmpty() && row.all { it.toContinueWatchingItem().title.isNotBlank() })
    }
